<section class="social-comments social-inline-panel" id="<?= !empty($selected) ? 'comments' : 'comments-' . (int)$postId ?>"><h2>Comments <span data-comments-total><?= (int)$commentsPost['comments'] ?></span></h2><div class="social-comment-list" data-comment-list><?php foreach ($commentChildren[0] ?? [] as $comment): $depth = 0; require __DIR__ . '/forum-comment.php'; endforeach; ?></div><?php if ($user): ?><button type="button" class="social-compose-toggle" data-compose-toggle>Write a comment</button><form method="post" class="social-comment-form social-composer" data-async-action="comment" hidden><input type="hidden" name="csrf" value="<?= app_h(app_csrf()) ?>"><input type="hidden" name="action" value="comment"><input type="hidden" name="post_id" value="<?= (int)$postId ?>"><label for="comment-body-<?= (int)$postId ?>">Add a comment</label><textarea id="comment-body-<?= (int)$postId ?>" name="body" rows="3" minlength="2" maxlength="3000" required></textarea><button type="submit">Post comment</button></form><?php else: ?><a href="signin">Sign in to comment →</a><?php endif; ?></section>
